import{_ as t,o,c as a,a2 as s}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"DevOps Capability — enumerated source for the DevOps Capability Assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/devops-capability-question-set.md","filePath":"frameworks/devops-capability-question-set.md"}'),r={name:"frameworks/devops-capability-question-set.md"};function i(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="devops-capability-—-enumerated-source-for-the-devops-capability-assessment" tabindex="-1">DevOps Capability — enumerated source for the DevOps Capability Assessment <a class="header-anchor" href="#devops-capability-—-enumerated-source-for-the-devops-capability-assessment" aria-label="Permalink to &quot;DevOps Capability — enumerated source for the DevOps Capability Assessment&quot;">​</a></h1><p><strong>Enumerated 2026-08-01. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p><strong>Framework version:</strong> Not versioned by Microsoft — the DevOps Capability Assessment carries no release number. The extraction date above (2026-08-01) is the version, per <code>docs/frameworks/README.md</code>; re-date this line when this file is next re-verified.</p><p>This is the AB#6815 enumeration for target #10 in the audit&#39;s fourteen-assessment programme (<code>pmo/audits/AZURE-SCOUT-AUDIT.md</code> §14): <em>&quot;DevOps Capability Assessment — 5 DevOps collectors exist via the ADO REST API … <code>caf.platformauto</code> (6 rules, ~8% coverage).&quot;</em> <code>caf.platformauto.yaml</code> scores the CAF Ready methodology&#39;s <strong>Platform automation and DevOps design area</strong> (§8 Table 2 — 30 recommendations, largely CI/CD process guidance ARM telemetry can&#39;t observe). This document is about a <strong>different</strong>, narrower, named assessment; the two overlap in subject matter but are not the same enumeration. Per the note in this Feature&#39;s brief, the five ADO collectors currently sit under <code>manifests/collectors/Management/DevOps*.psd1</code> pending relocation to the <code>DevOps/</code> category in a parallel workstream; they are cited below by collector name, not by their current path.</p><h2 id="what-the-devops-capability-assessment-is" tabindex="-1">What the DevOps Capability Assessment is <a class="header-anchor" href="#what-the-devops-capability-assessment-is" aria-label="Permalink to &quot;What the DevOps Capability Assessment is&quot;">​</a></h2><p>An interactive assessment on the Microsoft Assessments platform (<a href="https://learn.microsoft.com/en-us/assessments/56ec577c-acb6-4c7b-ad13-e224b0846153/" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/assessments/56ec577c-acb6-4c7b-ad13-e224b0846153/</a>), ~30 minutes, multiple-choice/multiple-response, described as helping organisations <em>&quot;understand current capabilities across the entire software release lifecycle … based on the Microsoft DevOps practices.&quot;</em> It also appears under its older name, <strong>DevOps Capability Assessment</strong>, in Microsoft&#39;s long-running Services Hub On-Demand Assessments catalogue, confirming it predates the Microsoft Assessments platform migration.</p><p>The CAF&#39;s own DevOps considerations page names the <strong>Microsoft DevOps Resource Center</strong> (<a href="https://learn.microsoft.com/en-us/devops/what-is-devops" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/devops/what-is-devops</a>) as the framework to use when building a DevOps capability, and cites this exact assessment as the tool to measure current-state against it. The Resource Center organises DevOps practice into five named phases — Plan, Develop/Continuous Integration, Continuous Delivery, Operations/Reliability, DevSecOps — and this enumeration is built from that published structure, cross-checked against the CAF DevOps-considerations page&#39;s own recommendations (metrics, toolchain, framework selection).</p><h2 id="verification-method-—-and-the-one-thing-this-enumeration-is-not" tabindex="-1">Verification method — and the one thing this enumeration is NOT <a class="header-anchor" href="#verification-method-—-and-the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;Verification method — and the one thing this enumeration is NOT&quot;">​</a></h2><p><strong>What was read (2026-08-01):</strong></p><table tabindex="0"><thead><tr><th>Source</th><th>What it gave</th></tr></thead><tbody><tr><td>The DevOps Capability Assessment landing page</td><td>Confirms the assessment exists, its duration/format, its explicit tie to Microsoft DevOps practices. <strong>No question text.</strong></td></tr><tr><td><a href="https://learn.microsoft.com/en-us/devops/what-is-devops" target="_blank" rel="noreferrer">What is DevOps?</a> (Microsoft DevOps Resource Center)</td><td>The five-phase structure (Plan, Develop, Deliver, Operate, DevSecOps) this enumeration is organised under</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/considerations/devops-principles-and-practices" target="_blank" rel="noreferrer">DevOps considerations</a></td><td>The explicit citation of this assessment as the tool for measuring current DevOps state; DORA-style software-delivery-performance metrics (lead time, deployment frequency, MTTR, change-fail %)</td></tr><tr><td><code>manifests/collectors/Management/DevOps*.psd1</code>, <code>manifests/collectors/DevOps/ManagedDevOpsPools.psd1</code></td><td>Ground truth for which ADO/DevOps fields Scout actually collects</td></tr></tbody></table><p><strong>⚠️ The assessment&#39;s own question TEXT and NUMBERS are not published.</strong> The <code>DEVOPS-*</code> identifiers below are <strong>Scout&#39;s own</strong>, built from the DevOps Resource Center&#39;s published phase structure, not Microsoft&#39;s question numbers.</p><p><strong>Shelf life.</strong> The DevOps Resource Center and CAF DevOps-considerations pages are actively maintained; re-verify before quoting.</p><h2 id="the-enumeration" tabindex="-1">The enumeration <a class="header-anchor" href="#the-enumeration" aria-label="Permalink to &quot;The enumeration&quot;">​</a></h2><h3 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>DEVOPS-PLN-01</td><td>Work is planned and tracked through Azure DevOps (or an equivalent) rather than ad hoc</td><td>✅ <code>DevOpsProjects</code></td></tr><tr><td>DEVOPS-PLN-02</td><td>Outcome-oriented metrics (OKRs, delivery performance, quality) are defined and tracked</td><td>❌ Organisational — no metric-definition artefact is ARM/ADO-API-visible</td></tr></tbody></table><h3 id="develop-continuous-integration" tabindex="-1">Develop / Continuous Integration <a class="header-anchor" href="#develop-continuous-integration" aria-label="Permalink to &quot;Develop / Continuous Integration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>DEVOPS-DEV-01</td><td>Source code is held in version-controlled repositories, not ad hoc file shares</td><td>✅ <code>DevOpsRepositories</code></td></tr><tr><td>DEVOPS-DEV-02</td><td>Continuous integration pipelines build and test on every change</td><td>⚠️ Partial — <code>DevOpsPipelines</code> records pipeline existence and configuration type, not trigger-on-commit behaviour or run history</td></tr><tr><td>DEVOPS-DEV-03</td><td>Pipelines are defined as YAML-as-code rather than authored through the classic UI editor</td><td>✅ <code>DevOpsPipelines</code> (&quot;Configuration Type&quot;, &quot;YAML Path&quot; fields)</td></tr></tbody></table><h3 id="deliver-continuous-delivery" tabindex="-1">Deliver / Continuous Delivery <a class="header-anchor" href="#deliver-continuous-delivery" aria-label="Permalink to &quot;Deliver / Continuous Delivery&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>DEVOPS-DEL-01</td><td>Deployments run through automated CI/CD pipelines rather than manual portal changes</td><td>⚠️ Partial — <code>$.management.deployments[?(@.properties.templateHash)]</code> (generic IaC signal, same as <code>CAF-AUT-01</code>), <code>DevOpsPipelines</code> existence</td></tr><tr><td>DEVOPS-DEL-02</td><td>Service connections authenticate via credential-free (workload identity federation), not long-lived secrets</td><td>✅ <code>DevOpsServiceConnections</code> (&quot;Credential Free&quot; field)</td></tr><tr><td>DEVOPS-DEL-03</td><td>Releases use safe-deployment practices — approvals, gates, canary/blue-green rollout</td><td>❌ Pipeline stage/approval/gate configuration is not collected</td></tr><tr><td>DEVOPS-DEL-04</td><td>Feature flags and progressive-exposure deployment strategies are used</td><td>❌ Not collected</td></tr></tbody></table><h3 id="operate-operations-and-reliability" tabindex="-1">Operate / Operations and Reliability <a class="header-anchor" href="#operate-operations-and-reliability" aria-label="Permalink to &quot;Operate / Operations and Reliability&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>DEVOPS-OPS-01</td><td>Build/release agent capacity uses managed pools rather than unmanaged self-hosted agents</td><td>✅ <code>ManagedDevOpsPools</code>, <code>DevOpsAgentPools</code> (&quot;Hosting Model&quot; field)</td></tr><tr><td>DEVOPS-OPS-02</td><td>Standardized, self-service developer environments are provisioned (Dev Centers / Dev Box)</td><td>✅ <code>DevCenters</code>, <code>DevBoxPools</code></td></tr><tr><td>DEVOPS-OPS-03</td><td>Load and resilience testing are part of the operational pipeline</td><td>⚠️ Partial — <code>LoadTesting</code>, <code>ChaosStudio</code> existence only, no test-run history</td></tr><tr><td>DEVOPS-OPS-04</td><td>Continuous monitoring instruments health, performance, and reliability across dev through production</td><td>⚠️ Partial — <code>Monitor/ActionGroups</code>, <code>Monitor/MetricAlertRules</code> are generic monitoring signals, not scoped to DevOps pipeline stages</td></tr><tr><td>DEVOPS-OPS-05</td><td>Software delivery performance is measured — lead time for change, deployment frequency, mean time to restore, change-failure percentage (the DORA four keys)</td><td>❌ Not collected — Scout has pipeline <em>definitions</em>, not run or deployment history, which is what these four metrics require</td></tr></tbody></table><h3 id="devsecops" tabindex="-1">DevSecOps <a class="header-anchor" href="#devsecops" aria-label="Permalink to &quot;DevSecOps&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>DEVOPS-SEC-01</td><td>Security and policy-compliance gates run in the pipeline before production promotion</td><td>❌ Pipeline stage/gate configuration and YAML content are not collected</td></tr><tr><td>DEVOPS-SEC-02</td><td>Automated pipelines enforce policy-as-code (DeployIfNotExists/Modify) for platform configuration</td><td>✅ <code>$.governance.policyAssignments[?(@.properties.parameters)]</code>, same signal as <code>CAF-AUT-02</code></td></tr><tr><td>DEVOPS-SEC-03</td><td>Repositories and build artefacts are scanned for vulnerabilities before deployment</td><td>❌ Not collected</td></tr><tr><td>DEVOPS-SEC-04</td><td>End-to-end functional/UI test automation is part of the release process</td><td>⚠️ Partial — <code>PlaywrightTesting</code> existence only, no test-run or pass-rate data</td></tr></tbody></table><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p><strong>6 of 18 items are fully answerable, 6 are partial, 6 are not collected at all.</strong> The pattern here is consistent with the audit&#39;s observation about #10 in §14: <em>&quot;mostly ready … inventory exists; they need rule files, not collectors.&quot;</em> Every fully-answerable item resolves to a collector Scout already has. The genuine gap is <strong>run-history data</strong> — <code>DEVOPS-OPS-05</code>&#39;s four DORA metrics, pipeline trigger-on-commit behaviour (<code>DEVOPS-DEV-02</code>), and approval-gate configuration (<code>DEVOPS-DEL-03</code>) all need the Azure DevOps <em>Pipelines Runs</em> / <em>Releases</em> APIs, which Scout&#39;s five ADO collectors do not call — they read project/repo/pipeline/service-connection/agent-pool <em>definitions</em>, not execution history. That is a materially different, heavier API surface (per-run pagination across every pipeline) and should be scoped as its own decision before any <code>caf.devops-capability.yaml</code> claims credit for delivery-performance scoring it cannot actually do.</p>',25)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
